    "ANSLIFE vận hành hệ thống máy móc và thiết bị phục vụ toàn bộ quá trình sản xuất, từ gia công vật liệu, hoàn thiện bề mặt, lắp ráp đến đóng gói. Việc đầu tư công nghệ phù hợp giúp đảm bảo độ chính xác của sản phẩm, ổn định chất lượng và đáp ứng tiến độ của các dự án xuất khẩu.": "ANSLIFE operates machinery and equipment systems serving the entire production process, from material processing, surface finishing, assembly to packaging. Investing in appropriate technology helps ensure product accuracy, stabilize quality and meet the schedule of export projects.",
    "Năng lực hoàn thiện": "Finishing capability",
