    "Vai trò của dây chuyền lắp ráp trong hệ thống sản xuất": "The role of the assembly line in the production system",
    "Dây chuyền lắp ráp là bước chuyển từ các linh kiện riêng lẻ thành sản phẩm hoàn chỉnh. Mọi sản phẩm đều được kiểm tra về kết cấu, chức năng và ngoại quan trước khi chuyển sang kiểm tra chất lượng cuối cùng và đóng gói.": "The assembly line is the step from individual components to finished products. Every product is tested for structure, function and appearance before moving on to final quality control and packaging.",
    "Quy trình lắp ráp được xây dựng phù hợp với từng nhóm sản phẩm nhằm đảm bảo tính đồng nhất, hiệu quả sản xuất và đáp ứng yêu cầu kỹ thuật của từng buyer.": "The assembly process is built to suit each product group to ensure uniformity, production efficiency and meet each buyer's technical requirements.",
    "Liên kết với các nội dung liên quan": "Link to related content",
    "Giới thiệu hệ thống tổ chức sản xuất của ANSLIFE.": "Introducing ANSLIFE's production organization system.",
