    "Buyer có thể gửi bản vẽ, mẫu sản phẩm, danh sách linh kiện hoặc tiêu chuẩn kỹ thuật để ANSLIFE đánh giá phương án lắp ráp, kiểm soát chất lượng và tổ chức sản xuất phù hợp.": "Buyers can send drawings, product samples, component lists or technical standards to ANSLIFE to evaluate appropriate assembly, quality control and production organization plans.",
    "Xem tổng quan nhà máy": "View factory overview",
