    "Thiết bị cắt foam, may và bọc nệm phục vụ các sản phẩm sofa, ghế và nội thất bọc nệm.": "Foam cutting, sewing and upholstery equipment serves sofa, chair and upholstered furniture products.",
    "6. Lắp ráp": "6. Assembly",
