    "Buyer có thể gửi quy cách sản phẩm, kích thước kiện hàng, tiêu chuẩn pallet hoặc lịch xuất hàng để ANSLIFE đánh giá và đề xuất phương án xếp container phù hợp.": "구매자는 ANSLIFE에 제품 사양, 패키지 크기, 팔레트 표준 또는 배송 일정을 보내 적절한 컨테이너 적재 옵션을 평가하고 제안할 수 있습니다.",
