    "Quy trình kiểm soát chất lượng trong toàn bộ hệ thống sản xuất.": "전체 생산 시스템에 걸친 품질 관리 프로세스.",
    "Vietnam Supply Hub": "베트남 공급 허브",
    "Giải pháp lưu kho, gom hàng và điều phối xuất khẩu.": "보관, 통합, 수출 조정을 위한 솔루션입니다.",
    "Trao đổi về năng lực sản xuất cho dự án của bạn": "프로젝트의 생산 능력에 대해 논의하세요.",
    "Buyer có thể gửi bản vẽ, mẫu sản phẩm, tiêu chuẩn chất lượng hoặc kế hoạch đơn hàng để ANSLIFE đánh giá năng lực sản xuất và đề xuất phương án vận hành phù hợp.": "구매자는 도면, 제품 샘플, 품질 표준 또는 주문 계획을 ANSLIFE에 보내 생산 능력을 평가하고 적절한 운영 계획을 제안할 수 있습니다.",
    "Gửi yêu cầu": "요청 보내기",
    "Tải bản vẽ lên": "그림 업로드",
    "Liên hệ ANSLIFE": "ANSLIFE에 문의하세요",
