    "Quy trình kiểm tra trước khi đóng gói và xuất khẩu.": "Inspektionsprocess före förpackning och export.",
    "Cần tổ chức quy trình lắp ráp cho dự án nội thất?": "Behöver du organisera monteringsprocessen för ett inredningsprojekt?",
    "Buyer có thể gửi bản vẽ, mẫu sản phẩm, danh sách linh kiện hoặc tiêu chuẩn kỹ thuật để ANSLIFE đánh giá phương án lắp ráp, kiểm soát chất lượng và tổ chức sản xuất phù hợp.": "Köpare kan skicka ritningar, produktprover, komponentlistor eller tekniska standarder till ANSLIFE för att utvärdera lämpliga planer för montering, kvalitetskontroll och produktionsorganisation.",
