    "1. Gia công gỗ": "1. Träbearbetning",
    "Máy cắt, máy cưa, máy bào, máy soi và các thiết bị gia công gỗ phục vụ sản xuất linh kiện và nội thất hoàn thiện.": "Skärmaskiner, sågar, hyvlar, skannrar och träbearbetningsutrustning betjänar tillverkning av komponenter och färdiga möbler.",
