    "Thiết bị cắt foam, may và bọc nệm phục vụ các sản phẩm sofa, ghế và nội thất bọc nệm.": "Skumskärning, sömnad och klädselutrustning serverar soffa, stolar och stoppade möbelprodukter.",
    "6. Lắp ráp": "6. Montering",
    "Khu vực và thiết bị hỗ trợ lắp ráp, kiểm tra kích thước và hoàn thiện sản phẩm trước khi kiểm tra chất lượng.": "Ytor och utrustning för att stödja montering, storlekskontroll och efterbehandling av produkter före kvalitetskontroll.",
    "7. Đóng gói": "7. Förpackning",
    "Thiết bị đóng gói, quấn màng, đai kiện và chuẩn bị pallet phục vụ xuất khẩu.": "Utrustning för packning, inslagning, balning och pallberedning för export.",
    "8. Thiết bị kiểm tra": "8. Testutrustning",
    "Thiết bị đo lường và kiểm tra hỗ trợ kiểm soát chất lượng trong quá trình sản xuất và trước khi xuất hàng.": "Mät- och testutrustning stöder kvalitetskontroll under produktion och före leverans.",
