    "Ưu tiên công nghệ giúp sử dụng vật liệu hiệu quả và giảm lãng phí trong sản xuất.": "Prioritera teknik som hjälper till att använda material effektivt och minska avfallet i produktionen.",
    "Cần đánh giá năng lực thiết bị cho dự án của bạn?": "Behöver du utvärdera utrustningens kapacitet för ditt projekt?",
    "ANSLIFE hỗ trợ lựa chọn phương án sản xuất phù hợp với yêu cầu kỹ thuật, tiêu chuẩn hoàn thiện và tiến độ giao hàng của từng dự án nội thất xuất khẩu.": "ANSLIFE stödjer valet av produktionsplaner som passar de tekniska kraven, färdigställandestandarderna och leveransschemat för varje exportmöbelprojekt.",
