    "Gia công khung ghế, mặt bàn, chân gỗ, chi tiết tủ, cấu kiện bọc nệm và linh kiện mây tre.": "Bearbetar stolsramar, bordsskivor, träben, skåpdetaljer, stoppade komponenter och rottingkomponenter.",
    "Gia công gỗ tự nhiên, gỗ kỹ thuật, vật liệu bọc và các chi tiết hoàn thiện.": "Bearbetning av naturligt trä, konstruerat trä, klädselmaterial och ytbehandlingsdetaljer.",
    "Kết nối sản xuất với lưu kho, gom hàng và điều phối xuất khẩu theo từng dự án.": "Koppla samman produktion med lager, konsolidera varor och samordna export efter varje projekt.",
