    "Kiểm tra nguyên liệu đầu vào, độ ẩm và tiêu chuẩn vật liệu trước khi đưa vào sản xuất.": "Kontrollera insatsmaterial, fukt och materialstandarder innan de sätts i produktion.",
    "Gia công gỗ, kim loại, mây tre và các cấu kiện theo bản vẽ kỹ thuật.": "Bearbetning av trä, metall, rotting och strukturer enligt tekniska ritningar.",
    "Chà nhám, sơn hoàn thiện, bọc nệm, lắp ráp và xử lý bề mặt.": "Slipning, finmålning, klädsel, montering och ytbehandling.",
