    "Kiểm tra vận hành": "Vérifier le fonctionnement",
    "Đánh giá khả năng đóng mở, liên kết và độ ổn định trước khi chuyển sang QC.": "Évaluez l’ouverture, la liaison et la stabilité avant de passer au contrôle qualité.",
