    "Lắp mặt bàn, chân bàn và hệ liên kết.": "Installez le plateau de table, les pieds de table et le système de connexion.",
    "Tủ & Kệ": "Armoires et étagères",
    "Lắp thân tủ, cánh, ray trượt, bản lề và phụ kiện.": "Installez le corps de l'armoire, les portes, les glissières, les charnières et les accessoires.",
    "Nội thất bọc nệm": "Meubles rembourrés",
    "Lắp khung, foam, vật liệu bọc và phụ kiện hoàn thiện.": "Installez les cadres, la mousse, les matériaux de rembourrage et les accessoires de finition.",
    "Nội thất mây tre": "Meubles en rotin",
    "Lắp khung, chi tiết đan và các bộ phận hoàn thiện.": "Installez le cadre, les détails tissés et les pièces de finition.",
    "OEM / ODM": "OEM/ODM",
    "Triển khai quy trình lắp ráp theo yêu cầu riêng của từng dự án.": "Déployer le processus d’assemblage selon les exigences spécifiques de chaque projet.",
    "Kiểm soát trong quá trình lắp ráp": "Contrôle lors du montage",
    "Linh kiện": "Composants",
    "Kiểm tra đầu vào": "Vérifier l'entrée",
    "Cân chỉnh": "Calibrage",
    "Chuyển sang QC cuối": "Passer au CQ final",
    "Ứng dụng": "Demande",
    "Nội thất hoàn thiện": "Intérieur complet",
    "Nội thất Knock-down (KD)": "Meubles démontables (KD)",
    "Dự án khách sạn và thương mại": "Projets hôteliers et commerciaux",
    "Vai trò của dây chuyền lắp ráp trong hệ thống sản xuất": "Le rôle de la chaîne de montage dans le système de production",
    "Dây chuyền lắp ráp là bước chuyển từ các linh kiện riêng lẻ thành sản phẩm hoàn chỉnh. Mọi sản phẩm đều được kiểm tra về kết cấu, chức năng và ngoại quan trước khi chuyển sang kiểm tra chất lượng cuối cùng và đóng gói.": "La chaîne d'assemblage est l'étape allant des composants individuels aux produits finis. Chaque produit est testé pour sa structure, sa fonction et son apparence avant de passer au contrôle qualité final et à l'emballage.",
    "Quy trình lắp ráp được xây dựng phù hợp với từng nhóm sản phẩm nhằm đảm bảo tính đồng nhất, hiệu quả sản xuất và đáp ứng yêu cầu kỹ thuật của từng buyer.": "Le processus d'assemblage est conçu pour s'adapter à chaque groupe de produits afin de garantir l'uniformité, l'efficacité de la production et de répondre aux exigences techniques de chaque acheteur.",
    "Liên kết với các nội dung liên quan": "Lien vers du contenu connexe",
    "Giới thiệu hệ thống tổ chức sản xuất của ANSLIFE.": "Présentation du système d'organisation de la production d'ANSLIFE.",
    "Các công nghệ và thiết bị phục vụ sản xuất.": "Technologies et équipements pour la production.",
    "Quy trình xử lý bề mặt và hoàn thiện sản phẩm.": "Processus de traitement de surface et de finition du produit.",
    "Quy trình kiểm tra trước khi đóng gói và xuất khẩu.": "Processus d’inspection avant emballage et exportation.",
    "Cần tổ chức quy trình lắp ráp cho dự án nội thất?": "Besoin d'organiser le processus de montage pour un projet d'intérieur ?",
    "Buyer có thể gửi bản vẽ, mẫu sản phẩm, danh sách linh kiện hoặc tiêu chuẩn kỹ thuật để ANSLIFE đánh giá phương án lắp ráp, kiểm soát chất lượng và tổ chức sản xuất phù hợp.": "Les acheteurs peuvent envoyer des dessins, des échantillons de produits, des listes de composants ou des normes techniques à ANSLIFE pour évaluer les plans d'assemblage, de contrôle qualité et d'organisation de la production appropriés.",
    "Xem tổng quan nhà máy": "Voir l'aperçu de l'usine",
    "Năng lực hoàn thiện của ANSLIFE": "Capacité de finition d’ANSLIFE",
    "Hoàn thiện gỗ tự nhiên": "Finition bois naturel",
    "Giữ nguyên vẻ đẹp của vân gỗ hoặc xử lý màu sắc theo yêu cầu của từng bộ sưu tập.": "Entretenez la beauté du grain du bois ou traitez la couleur selon les exigences de chaque collection.",
    "Hoàn thiện gỗ kỹ thuật": "Finition technique du bois",
    "Áp dụng các giải pháp sơn và vật liệu phủ bề mặt nhằm tạo tính đồng nhất và độ bền cho sản phẩm.": "Appliquez des solutions de peinture et des matériaux de revêtement de surface pour créer l'uniformité et la durabilité du produit.",
    "Hoàn thiện nội thất bọc nệm": "Intérieur entièrement rembourré",
