    "Buyer có thể gửi bản vẽ, mẫu sản phẩm, tiêu chuẩn chất lượng hoặc kế hoạch đơn hàng để ANSLIFE đánh giá năng lực sản xuất và đề xuất phương án vận hành phù hợp.": "Les acheteurs peuvent envoyer des dessins, des échantillons de produits, des normes de qualité ou des plans de commande à ANSLIFE pour évaluer la capacité de production et proposer des plans d'exploitation appropriés.",
    "Gửi yêu cầu": "Envoyer la demande",
    "Tải bản vẽ lên": "Télécharger le dessin",
    "Liên hệ ANSLIFE": "Contacter ANSLIFE",
    "Banner tổng quan nhà máy": "Bannière aperçu de l’usine",
    "Banner máy móc và thiết bị": "Bannière machines et équipements",
    "Banner năng lực hoàn thiện": "Bannière capacité de finition",
    "Banner dây chuyền lắp ráp": "Bannière ligne d’assemblage",
