    "Những yếu tố được kiểm soát": "Эти факторы контролируются",
    "Xác nhận số lượng, mã hàng và tình trạng đóng gói trước khi xếp.": "Перед загрузкой подтвердите количество, код продукта и состояние упаковки.",
    "Đảm bảo pallet ổn định, đúng tải trọng và phù hợp với phương án xếp hàng.": "Убедитесь, что поддон устойчив, имеет правильную нагрузку и соответствует плану погрузки.",
    "Bố trí trọng lượng hợp lý nhằm đảm bảo cân bằng container trong quá trình vận chuyển.": "Обеспечьте разумный вес, чтобы обеспечить баланс контейнера во время транспортировки.",
    "Cố định hàng hóa": "Ремонт товаров",
    "Sử dụng dây đai, thanh chèn và vật liệu bảo vệ để hạn chế dịch chuyển.": "Используйте ремни, упоры и защитные материалы, чтобы ограничить движения.",
    "Kiểm tra khoảng trống": "Проверьте пространство",
    "Hạn chế khoảng trống lớn giúp giảm rung lắc và va chạm giữa các kiện hàng.": "Ограничение больших зазоров помогает уменьшить вибрацию и столкновения между упаковками.",
    "Kiểm tra trước niêm phong": "Проверьте перед герметизацией",
    "Đánh giá toàn bộ container trước khi đóng cửa và bàn giao cho đơn vị vận chuyển.": "Оцените весь контейнер перед закрытием и передачей в отдел отгрузки.",
    "Các loại hình xếp hàng": "Типы очередей",
    "Nội thất nguyên chiếc": "Полный интерьер",
    "Xếp theo kích thước và khả năng chịu tải của từng sản phẩm.": "Расположите в соответствии с размером и грузоподъемностью каждого продукта.",
    "Knock-down (KD)": "Нокдаун (КД)",
    "Tối ưu thể tích bằng cách xếp theo từng kiện và bộ sản phẩm.": "Оптимизируйте объем, упорядочив каждую упаковку и набор продуктов.",
    "Linh kiện nội thất": "Компоненты интерьера",
    "Gom pallet theo mã hàng hoặc từng dự án.": "Соберите поддоны по коду продукта или проекту.",
    "Hàng hỗn hợp (Mixed Container)": "Смешанный контейнер (Смешанный контейнер)",
    "Kết hợp nhiều nhóm sản phẩm trong cùng container theo kế hoạch giao hàng.": "Объедините несколько групп товаров в одном контейнере в соответствии с планом доставки.",
    "LCL": "LCL",
    "Chuẩn bị kiện hàng phù hợp với vận chuyển ghép container.": "Подготовьте пакеты, подходящие для контейнерной перевозки.",
    "FCL": "ФКЛ",
    "Triển khai phương án xếp tối ưu cho container nguyên.": "Реализуйте оптимальный план загрузки контейнеров с сырьем.",
    "Năng lực xếp container của ANSLIFE": "Грузоподъемность контейнеров ANSLIFE",
    "Lập sơ đồ xếp hàng": "Составьте диаграмму очередей",
    "Xây dựng phương án xếp container theo kích thước và tải trọng thực tế.": "Разработайте план загрузки контейнера в соответствии с фактическим размером и загрузкой.",
    "Kiểm soát an toàn": "Контроль безопасности",
    "Đảm bảo hàng hóa được cố định chắc chắn trong suốt quá trình vận chuyển.": "Убедитесь, что товар надежно зафиксирован во время транспортировки.",
    "Phối hợp Logistics": "Координация логистики",
    "Kết nối với đơn vị vận chuyển và lịch xuất hàng để đảm bảo tiến độ.": "Свяжитесь с единицами отгрузки и графиками поставок, чтобы обеспечить прогресс.",
    "Hỗ trợ Supply Hub": "Поддержка Центра поставок",
    "Thực hiện gom hàng từ nhiều nhà máy và tổ chức xếp container tại Vietnam Supply Hub.": "Консолидируйте товары со многих заводов и организуйте погрузку контейнеров во Вьетнамском центре поставок.",
    "Xếp container trong chuỗi cung ứng của ANSLIFE": "Штабелируйте контейнеры в цепочке поставок ANSLIFE",
    "Sản xuất": "Производство",
