    "Cần lập phương án xếp container cho đơn hàng xuất khẩu?": "Вам нужно составить план загрузки контейнера для экспортных заказов?",
    "Buyer có thể gửi quy cách sản phẩm, kích thước kiện hàng, tiêu chuẩn pallet hoặc lịch xuất hàng để ANSLIFE đánh giá và đề xuất phương án xếp container phù hợp.": "Покупатели могут отправлять в ANSLIFE спецификации продукта, размеры упаковки, стандарты поддонов или графики доставки, чтобы они могли оценить и предложить подходящие варианты загрузки контейнера.",
    "Trao đổi dự án": "Обмен проектами",
    "LCL / FCL Consolidation": "Консолидация LCL/FCL",
    "Các công đoạn trong khu vực đóng gói": "Этапы работы в области упаковки",
    "Kiểm tra ngoại quan": "Проверьте внешний вид",
    "Kiểm tra tình trạng sản phẩm sau lắp ráp và trước khi đóng gói.": "Проверьте состояние изделия после сборки и перед упаковкой.",
    "Vệ sinh sản phẩm": "Очистка продукта",
    "Làm sạch bụi, dấu bẩn và kiểm tra bề mặt hoàn thiện.": "Очистите пыль, следы грязи и проверьте качество поверхности.",
    "Bảo vệ sản phẩm": "Защита продукта",
