    "Lập sơ đồ xếp hàng": "Hacer un diagrama de colas",
    "Xây dựng phương án xếp container theo kích thước và tải trọng thực tế.": "Desarrollar un plan de carga de contenedores de acuerdo con el tamaño y la carga reales.",
    "Kiểm soát an toàn": "control de seguridad",
    "Đảm bảo hàng hóa được cố định chắc chắn trong suốt quá trình vận chuyển.": "Asegúrese de que la mercancía esté fijada de forma segura durante el transporte.",
    "Phối hợp Logistics": "Coordinación de Logística",
    "Kết nối với đơn vị vận chuyển và lịch xuất hàng để đảm bảo tiến độ.": "Conéctese con unidades de envío y cronogramas de entrega para garantizar el progreso.",
    "Hỗ trợ Supply Hub": "Soporte del centro de suministro",
    "Thực hiện gom hàng từ nhiều nhà máy và tổ chức xếp container tại Vietnam Supply Hub.": "Consolide productos de muchas fábricas y organice la carga de contenedores en Vietnam Supply Hub.",
    "Xếp container trong chuỗi cung ứng của ANSLIFE": "Apilar contenedores en la cadena de suministro de ANSLIFE",
    "Sản xuất": "Producción",
    "QC cuối": "Control de calidad final",
    "Đóng gói": "Embalaje",
    "Pallet hóa": "paletización",
    "Xuất khẩu": "Exportar",
    "Giao hàng": "Entrega",
    "Cần lập phương án xếp container cho đơn hàng xuất khẩu?": "¿Necesita realizar un plan de carga de contenedores para pedidos de exportación?",
    "Buyer có thể gửi quy cách sản phẩm, kích thước kiện hàng, tiêu chuẩn pallet hoặc lịch xuất hàng để ANSLIFE đánh giá và đề xuất phương án xếp container phù hợp.": "Los compradores pueden enviar especificaciones del producto, dimensiones del paquete, estándares de paletas o cronogramas de envío para que ANSLIFE evalúe y proponga opciones apropiadas de carga de contenedores.",
    "Trao đổi dự án": "Intercambio de proyectos",
    "LCL / FCL Consolidation": "Consolidación LCL/FCL",
    "Các công đoạn trong khu vực đóng gói": "Pasos en el área de embalaje.",
    "Kiểm tra ngoại quan": "comprobar apariencia",
    "Kiểm tra tình trạng sản phẩm sau lắp ráp và trước khi đóng gói.": "Verifique el estado del producto después del ensamblaje y antes del embalaje.",
    "Vệ sinh sản phẩm": "Limpieza del producto",
    "Làm sạch bụi, dấu bẩn và kiểm tra bề mặt hoàn thiện.": "Limpiar el polvo, las marcas de suciedad y comprobar el acabado de la superficie.",
    "Bảo vệ sản phẩm": "Protección del producto",
    "Sử dụng túi PE, foam bảo vệ, bảo vệ cạnh và các vật liệu phù hợp để giảm rủi ro hư hỏng.": "Utilice bolsas de PE, espuma protectora, protectores de bordes y materiales adecuados para reducir el riesgo de daños.",
    "Đóng thùng": "cerrar la caja",
    "Đóng gói theo đúng quy cách, kích thước và hướng dẫn của từng dự án.": "Empacar según especificaciones, dimensiones e instrucciones de cada proyecto.",
    "Ghi nhãn": "Etiquetado",
    "Dán nhãn sản phẩm, mã hàng, ký hiệu vận chuyển và các thông tin theo yêu cầu của buyer.": "Etiquetar productos, códigos de producto, símbolos de envío y otra información según lo solicite el comprador.",
    "Chuyển sang khu vực xuất hàng": "Cambiar a la zona de envío",
    "Kiện hàng được chuyển đến khu vực pallet hoặc chờ xếp container.": "El paquete es trasladado a la zona de pallets o a la espera de carga del contenedor.",
    "Hệ thống vật liệu đóng gói": "Sistema de material de embalaje",
    "Túi PE": "Bolsa de polietileno",
    "Bảo vệ bề mặt khỏi bụi và hơi ẩm.": "Proteja la superficie del polvo y la humedad.",
    "Foam bảo vệ": "Protección de espuma",
    "Giảm va đập và chống rung.": "Reducir el impacto y la vibración.",
    "Bảo vệ cạnh": "Protección de bordes",
    "Bảo vệ các góc và cạnh dễ hư hỏng.": "Protege esquinas y bordes que se dañan fácilmente.",
    "Thùng carton": "cartón",
    "Bao bì chính của sản phẩm.": "Embalaje principal del producto.",
    "Đai kiện": "cinturón de demanda",
    "Giữ kiện hàng ổn định trong quá trình vận chuyển.": "Mantenga el paquete estable durante el transporte.",
    "Chuẩn bị cho lưu kho và xếp container.": "Prepárese para el almacenamiento y la carga de contenedores.",
    "Quy trình đóng gói": "Proceso de embalaje",
    "Sản phẩm hoàn thiện": "Producto terminado",
    "Làm sạch sản phẩm": "Limpiar el producto",
    "Lắp vật liệu bảo vệ": "Instalar material protector.",
    "Đóng thùng carton": "cerrar la caja",
    "Dán nhãn": "Etiqueta",
    "Đặt lên pallet": "Colocar en palet",
    "Chờ xuất hàng": "Esperando envío",
    "Quy cách đóng gói": "Especificaciones de embalaje",
    "Đảm bảo đúng theo tiêu chuẩn của từng buyer hoặc từng thị trường.": "Velar por el cumplimiento de los estándares de cada comprador o de cada mercado.",
    "Vật liệu đóng gói": "Materiales de embalaje",
    "Kiểm tra chất lượng và tình trạng của tất cả vật liệu trước khi sử dụng.": "Verifique la calidad y el estado de todos los materiales antes de su uso.",
    "Nhãn sản phẩm": "Etiqueta del producto",
    "Kiểm tra mã hàng, số lượng, ký hiệu và thông tin vận chuyển.": "Verifique el código del producto, la cantidad, el símbolo y la información de envío.",
    "Độ an toàn": "Nivel de seguridad",
    "Đảm bảo sản phẩm được cố định chắc chắn trong thùng.": "Asegúrese de que el producto esté firmemente fijado en la caja.",
    "Kiểm tra cách sắp xếp kiện hàng trên pallet trước khi lưu kho.": "Compruebe cómo están dispuestos los paquetes en los palés antes de almacenarlos.",
    "Kiểm tra cuối": "control final",
    "Xác nhận kiện hàng đạt yêu cầu trước khi chuyển sang khu vực xuất hàng.": "Confirme que el paquete cumpla con los requisitos antes de pasar al área de envío.",
    "Năng lực đóng gói của ANSLIFE": "Capacidad de envasado de ANSLIFE",
    "Đóng gói theo tiêu chuẩn Buyer": "Embalado según los estándares del comprador.",
    "Thực hiện theo quy cách, hướng dẫn và tiêu chuẩn riêng của từng khách hàng.": "Seguir las especificaciones, instrucciones y estándares de cada cliente.",
    "Đóng gói OEM / ODM": "Embalaje OEM/ODM",
    "Hỗ trợ in logo, mã sản phẩm, hướng dẫn lắp ráp và nhận diện thương hiệu.": "Admite la impresión de logotipos, códigos de productos, instrucciones de montaje y reconocimiento de marca.",
