    "Sơn hoặc hoàn thiện": "Pintado o terminado",
    "Sấy khô": "Secado",
    "Kiểm tra màu sắc": "comprobar el color",
    "Màu sắc": "Color",
    "Đảm bảo đồng với mẫu duyệt và đồng đều giữa các lô sản xuất.": "Garantice la coherencia con las muestras de aprobación y la uniformidad entre los lotes de producción.",
    "Độ đồng đều": "Uniformidad",
    "Kiểm soát sự nhất quán trên toàn bộ bề mặt sản phẩm.": "Controle la consistencia en toda la superficie del producto.",
    "Chất lượng bề mặt": "Calidad superficial",
    "Kiểm tra độ mịn, độ phủ và ngoại quan sau hoàn thiện.": "Comprobar suavidad, cobertura y aspecto tras el acabado.",
    "Liên kết lớp phủ": "Unión superpuesta",
    "Đảm bảo lớp hoàn thiện bám chắc vào bề mặt vật liệu.": "Asegúrese de que el acabado se adhiera firmemente a la superficie del material.",
    "Kiểm tra ánh sáng": "comprobar la iluminación",
    "Đánh giá màu sắc và ngoại quan dưới điều kiện ánh sáng tiêu chuẩn.": "Evalúe el color y la apariencia en condiciones de iluminación estándar.",
    "Đánh giá tổng thể trước khi chuyển sang công đoạn đóng gói.": "Evaluación global antes de pasar a la etapa de envasado.",
    "Nội thất gia đình": "muebles para el hogar",
