    "Dự án xuất khẩu": "Proyecto de exportación",
    "Hoàn thiện trong hệ thống chất lượng của ANSLIFE": "Perfección en el sistema de calidad de ANSLIFE",
    "Tất cả các công đoạn hoàn thiện đều được đối chiếu với mẫu đã được phê duyệt và kiểm tra theo tiêu chuẩn chất lượng của từng dự án.": "Todas las etapas de acabado se comparan con muestras aprobadas y se inspeccionan de acuerdo con los estándares de calidad de cada proyecto.",
    "Quá trình kiểm tra bao gồm màu sắc, ngoại quan, độ đồng đều và các yêu cầu kỹ thuật riêng của buyer trước khi sản phẩm được chuyển sang lắp ráp và đóng gói.": "El proceso de inspección incluye el color, la apariencia, la uniformidad y los requisitos técnicos propios del comprador antes de que el producto pase al ensamblaje y embalaje.",
    "Vai trò của hoàn thiện trong chuỗi giá trị": "El papel del cumplimiento en la cadena de valor",
    "Tăng giá trị thẩm mỹ": "Aumentar el valor estético.",
    "Nâng cao trải nghiệm người dùng": "Mejorar la experiencia del usuario",
