    "Khách hàng": "Clientes",
    "Phát triển sản phẩm": "Desarrollo de productos",
    "Lựa chọn nhà máy phù hợp": "Elija la fábrica adecuada",
    "Tổ chức sản xuất": "organización de producción",
    "QC độc lập": "Control de calidad independiente",
    "Năng lực sản xuất": "Capacidad de producción",
    "Sản xuất ghế, bàn, tủ, giường, kệ và các dòng nội thất hoàn thiện theo yêu cầu của khách hàng.": "Producción de sillas, mesas, armarios, camas, estanterías y líneas completas de muebles según los requerimientos del cliente.",
    "Gia công khung ghế, mặt bàn, chân ghế, chi tiết tủ, các khối bọc nệm và linh kiện mây tre.": "Procesamiento de estructuras de sillas, tableros de mesas, patas de sillas, detalles de armarios, bloques de tapizado y componentes de ratán.",
    "Gia công vật liệu": "Materiales de procesamiento",
    "Gia công gỗ tự nhiên, gỗ kỹ thuật, ván MDF và các chi tiết hoàn thiện.": "Procesamiento de madera natural, madera de ingeniería, tableros MDF y detalles de acabado.",
    "Phát triển và sản xuất sản phẩm theo bản vẽ, mẫu hoặc yêu cầu kỹ thuật của buyer.": "Desarrollar y fabricar productos según los dibujos, muestras o requisitos técnicos del comprador.",
    "Kết nối sản xuất với lưu kho, gom hàng và đáp ứng đơn xuất theo từng dự án.": "Conecte la producción con el almacenamiento, recopile mercancías y atienda pedidos para cada proyecto.",
    "1. Gia công gỗ": "1. Procesamiento de madera",
    "Máy cắt, máy cưa, máy bào, máy soi và các thiết bị gia công gỗ phục vụ sản xuất linh kiện và nội thất hoàn thiện.": "Para la producción de componentes y muebles acabados se utilizan máquinas cortadoras, sierras, cepilladoras, escáneres y equipos para trabajar la madera.",
    "2. Gia công CNC": "2. Mecanizado CNC",
    "Máy CNC phục vụ cắt, khoan, phay và gia công các chi tiết có độ chính xác cao theo bản vẽ kỹ thuật.": "Las máquinas CNC sirven para cortar, taladrar, fresar y mecanizar piezas de alta precisión según planos técnicos.",
    "3. Chà nhám": "3. Lijado",
    "Hệ thống chà nhám giúp tạo bề mặt đồng đều trước khi hoàn thiện sơn hoặc lắp ráp.": "El sistema de lijado ayuda a crear una superficie uniforme antes de terminar de pintar o ensamblar.",
    "4. Sơn hoàn thiện": "4. Acabado de pintura",
    "Thiết bị phun sơn, buồng sơn và hệ thống sấy phục vụ nhiều phương pháp hoàn thiện bề mặt theo yêu cầu của từng dự án.": "Los equipos de pulverización de pintura, cabinas de pintura y sistemas de secado sirven para una variedad de métodos de acabado de superficies según los requisitos de cada proyecto.",
    "5. Bọc nệm": "5. Funda de colchón",
    "Thiết bị cắt foam, may và bọc nệm phục vụ các sản phẩm sofa, ghế và nội thất bọc nệm.": "Los equipos de corte, costura y tapicería de espuma sirven para productos de sofás, sillas y muebles tapizados.",
    "6. Lắp ráp": "6. Asamblea",
    "Khu vực và thiết bị hỗ trợ lắp ráp, kiểm tra kích thước và hoàn thiện sản phẩm trước khi kiểm tra chất lượng.": "Áreas y equipos de apoyo al montaje, verificación de tamaños y acabado del producto antes de la inspección de calidad.",
    "7. Đóng gói": "7. Embalaje",
    "Thiết bị đóng gói, quấn màng, đai kiện và chuẩn bị pallet phục vụ xuất khẩu.": "Equipos de embalaje, enfardado, enfardado y preparación de pallets para exportación.",
    "8. Thiết bị kiểm tra": "8. Equipo de prueba",
    "Thiết bị đo lường và kiểm tra hỗ trợ kiểm soát chất lượng trong quá trình sản xuất và trước khi xuất hàng.": "Los equipos de medición y prueba respaldan el control de calidad durante la producción y antes del envío.",
    "Công nghệ gia công": "tecnología de mecanizado",
    "Gia công CNC": "Mecanizado CNC",
    "Gia công chính xác theo bản vẽ kỹ thuật.": "Mecanizado de precisión según dibujos técnicos.",
    "Đảm bảo độ chính xác của các mối liên kết và chi tiết sản phẩm.": "Garantizar la precisión de las conexiones y los detalles del producto.",
    "Tạo bề mặt đồng đều trước khi hoàn thiện.": "Cree una superficie uniforme antes de terminar.",
    "Phun sơn": "pintura en aerosol",
    "Đáp ứng nhiều hệ sơn và yêu cầu hoàn thiện khác nhau.": "Cumple con muchos sistemas de pintura diferentes y requisitos de acabado.",
    "Bọc nệm": "Funda de colchón",
    "Gia công các sản phẩm bọc với độ chính xác và tính thẩm mỹ cao.": "Procesamiento de productos tapizados con alta precisión y estética.",
    "Chuẩn bị sản phẩm theo tiêu chuẩn xuất khẩu quốc tế.": "Elaborar productos según estándares internacionales de exportación.",
    "Năng lực hỗ trợ sản xuất": "Capacidad de soporte a la producción",
