    "Cải thiện năng suất và tối ưu quy trình sản xuất.": "Mejorar la productividad y optimizar los procesos productivos.",
    "Phát triển bền vững": "Desarrollo sostenible",
    "Ưu tiên công nghệ giúp sử dụng vật liệu hiệu quả và giảm lãng phí trong sản xuất.": "Priorizar la tecnología que ayude a utilizar los materiales de forma eficaz y reducir los residuos en la producción.",
    "Cần đánh giá năng lực thiết bị cho dự án của bạn?": "¿Necesita evaluar la capacidad del equipo para su proyecto?",
    "ANSLIFE hỗ trợ lựa chọn phương án sản xuất phù hợp với yêu cầu kỹ thuật, tiêu chuẩn hoàn thiện và tiến độ giao hàng của từng dự án nội thất xuất khẩu.": "ANSLIFE apoya en la selección de planes de producción adecuados a los requisitos técnicos, estándares de finalización y cronograma de entrega de cada proyecto de mobiliario de exportación.",
    "Quy trình QC": "proceso de control de calidad",
    "Hệ thống sản xuất của ANSLIFE": "Sistema de producción ANSLIFE",
    "Gia công khung ghế, mặt bàn, chân gỗ, chi tiết tủ, cấu kiện bọc nệm và linh kiện mây tre.": "Procesamiento de estructuras de sillas, tableros de mesa, patas de madera, detalles de gabinetes, componentes tapizados y componentes de ratán.",
    "Gia công gỗ tự nhiên, gỗ kỹ thuật, vật liệu bọc và các chi tiết hoàn thiện.": "Procesamiento de madera natural, madera de ingeniería, materiales de tapicería y detalles de acabado.",
    "Kết nối sản xuất với lưu kho, gom hàng và điều phối xuất khẩu theo từng dự án.": "Conectando producción con almacenamiento, consolidando mercancías y coordinando exportaciones según cada proyecto.",
    "Hệ thống sản xuất": "Sistema de producción",
    "Chuẩn bị vật liệu": "preparar materiales",
    "Kiểm tra nguyên liệu đầu vào, độ ẩm và tiêu chuẩn vật liệu trước khi đưa vào sản xuất.": "Verifique los materiales de entrada, la humedad y los estándares de los materiales antes de ponerlos en producción.",
    "Gia công gỗ, kim loại, mây tre và các cấu kiện theo bản vẽ kỹ thuật.": "Procesamiento de madera, metal, ratán y estructuras según planos técnicos.",
    "Chà nhám, sơn hoàn thiện, bọc nệm, lắp ráp và xử lý bề mặt.": "Lijado, acabado de pintura, tapizado, montaje y tratamiento superficial.",
    "Kiểm tra chất lượng": "control de calidad",
    "Kiểm soát chất lượng tại từng công đoạn và kiểm tra cuối trước khi đóng gói.": "Control de calidad en cada etapa e inspección final antes del envasado.",
    "Đóng gói & Xuất khẩu": "Embalaje y exportación",
    "Đóng gói theo tiêu chuẩn buyer, lưu kho và điều phối xuất khẩu.": "Embalaje según estándares del comprador, almacenaje y coordinación de exportación.",
    "Các nhóm sản phẩm sản xuất": "Grupos de productos de fabricación",
