    "Kiểm soát vật liệu": "control de materiales",
    "Kiểm tra nguyên liệu theo tiêu chuẩn kỹ thuật trước khi sản xuất.": "Verifique las materias primas de acuerdo con las normas técnicas antes de la producción.",
    "Kiểm soát sản xuất": "control de producción",
    "Theo dõi từng công đoạn nhằm đảm bảo đúng quy trình và bản vẽ.": "Supervise cada paso para garantizar que los procedimientos y dibujos sean correctos.",
    "QC độc lập trong suốt quá trình sản xuất và trước khi xuất hàng.": "Control de calidad independiente durante todo el proceso de producción y antes del envío.",
    "Kiểm soát tiến độ": "Control de progreso",
    "Theo dõi kế hoạch sản xuất và tiến độ giao hàng của từng dự án.": "Monitorear los planes de producción y cronogramas de entrega de cada proyecto.",
