    "Buyer có thể gửi bản vẽ, mẫu sản phẩm, danh sách linh kiện hoặc tiêu chuẩn kỹ thuật để ANSLIFE đánh giá phương án lắp ráp, kiểm soát chất lượng và tổ chức sản xuất phù hợp.": "买家可以将图纸、产品样品、零部件清单或技术标准发送给 ANSLIFE，以评估适当的装配、质量控制和生产组织计划。",
    "Xem tổng quan nhà máy": "查看工厂概况",
